    float4 lightFx(float3 L) { L = clamp(L, 0.0, 1.0); return float4(L, max(L.r, max(L.g, L.b))); }
    float prog(float p) { return (amzp_autop>0.5) ? p + time * (amzp_autoSpeed * 0.5) : p; }
    float2 l2s(float2 v) { return (float4(v, 0.0, 1.0) * amzLayerToScreen()).xy; }
    bool inside(float2 uv) { return uv.x >= 0.0 && uv.x <= 1.0 && uv.y >= 0.0 && uv.y <= 1.0; }
    float4 layerAt(float2 uv) { return inside(uv) ? amzTexture(0, l2s(uv)) : float4(0.0); }
    float pxs() { return screen.zw.x / max(screen.zw.x, 1.0); }
    float3 hue(float h) { return clamp(abs(mod(h * 6.0 + float3(0.0, 4.0, 2.0), 6.0) - 3.0) - 1.0, 0.0, 1.0); }
    float hh(float x) { return fract(sin(x * 91.345 + amzp_seed * 13.7) * 43758.5453); }
    float vn1(float x) { float i = floor(x), f = fract(x); f = f * f * (3.0 - 2.0 * f); return mix(hh(i), hh(i + 1.0), f); }
    float hs(float2 p, float k) { return fract(sin(dot(p, float2(127.1, 311.7)) + k * 74.7 + amzp_seed * 3.91) * 43758.5453); }
    float3 hueRot(float3 c, float a) {
        float cs = cos(a), sn = sin(a);
        float3 k = float3(0.57735);
        return c * cs + cross(k, c) * sn + k * dot(k, c) * (1.0 - cs);
    }
    float3 pcol(float h) {
        float3 c;
        if (int(amzp_palette) == 1) c = mix(float3(1.0, 0.45, 0.75), float3(1.0, 0.8, 0.9), h);
        else if (int(amzp_palette) == 2) c = mix(float3(0.2, 0.85, 1.0), float3(0.7, 1.0, 1.0), h);
        else if (int(amzp_palette) == 3) c = mix(float3(0.9, 0.95, 1.0), float3(1.0), h);
        else if (int(amzp_palette) == 4) c = mix(hue(h), float3(1.0), 0.2);
        else if (int(amzp_palette) == 5) c = h < 0.5 ? mix(float3(0.2, 1.0, 0.55), float3(0.2, 0.8, 1.0), h * 2.0) : mix(float3(0.2, 0.8, 1.0), float3(0.7, 0.4, 1.0), h * 2.0 - 1.0);
        else if (int(amzp_palette) == 6) c = mix(amzp_color1.rgb, amzp_color2.rgb, h);
        else c = mix(float3(1.0, 0.72, 0.25), float3(1.0, 0.92, 0.6), h);
        return amzp_colorCycle != 0.0 ? hueRot(c, prog(amzp_evolution) * amzp_colorCycle) : c;
    }
    float rays(float2 d, float r, float rot) {
        if (int(amzp_starShape) == 0) return 0.0;
        float n = float(int(amzp_starShape) + 1);
        float s = 0.0;
        for (int k = 0; k < 4; k++) {
            if (float(k) >= n) break;
            float a = rot + float(k) * 3.14159265 / n;
            float2 ax = float2(cos(a), sin(a));
            float al = abs(dot(d, ax));
            float pp = abs(d.x * ax.y - d.y * ax.x);
            float wgt = (int(amzp_starShape) == 3 && mod(float(k), 2.0) > 0.5) ? 0.5 : 1.0;
            s += exp(-pp / (r * 0.09)) * exp(-al / (r * 3.2 * amzp_starLen)) * wgt;
