    float2 glim(float2 d, float r, float rot, float lim, float sm) {
        float dl = length(d);
        float core = exp(-pow(dl / (r * 0.55), 2.0)) * 1.2;
        float amzSource_gl = (exp(-dl / (r * 2.2)) * 0.35 + exp(-dl / (r * 7.0)) * 0.06) * amzp_glow;
        float st = (sm > 0.0 && dl < r * 25.0 * amzp_starLen) ? rays(d, r, rot) * 0.8 * sm : 0.0;
        float lf = 1.0 - smoothstep(0.5 * lim, 0.97 * lim, dl);
        return float2(core, (amzSource_gl + st) * lf);
    }
    float pulse(float ph, float sharp) { return pow(max(sin(ph * 3.14159265), 0.0), sharp); }
    void nmMain() {
        float2 W = layer;
        float2 uv = amzLayerNorm();
        float4 orig = layerAt(uv);
        float px = pxs();
        float sc = 1.0;
        float2 w = nmStdUp(uv * W - W * 0.5, px) / px;
        float evo = prog(amzp_evolution);
        float amt = clamp(amzp_amount, 0.0, 1.0);
        float tsp = max(amzp_twinkleSpeed, 0.01);
        float tws = mix(0.4, 5.0, clamp(amzp_twinkle, 0.0, 1.0));
        int nl = int(clamp(floor(amzp_layers + 0.5), 1.0, 5.0));
        float3 L = float3(0.0);
        if (int(amzp_mode) <= 3 || int(amzp_mode) == 8) {
            for (int l = 0; l < 5; l++) {
                if (l >= nl) break;
                float fl = float(l);
                float dp = nl > 1 ? fl / float(nl - 1) : 0.5;
                float zs = mix(0.6, 1.6, dp);
                float zv = mix(0.5, 1.5, dp);
                float cs = (int(amzp_mode) == 1 ? 50.0 : (int(amzp_mode) == 3 ? 260.0 : (int(amzp_mode) == 8 ? 170.0 : 130.0))) * sc * mix(0.85, 1.4, dp);
                float nat = int(amzp_mode) == 0 || int(amzp_mode) == 1 ? 90.0 : 90.0;
