                float2 dir = float2(cos(da), -sin(da));
                float spd = (int(amzp_mode) == 0 ? 0.12 : (int(amzp_mode) == 1 ? 0.08 : (int(amzp_mode) == 3 ? 0.25 : 0.6)));
                float2 off = dir * evo * amzp_driftSpeed * 300.0 * zv * spd;
                float2 f = (w - off) / cs + float2(fl * 13.7, fl * 5.3);
                float2 ci = floor(f);
                for (int j = -1; j <= 1; j++) {
                    for (int i = -1; i <= 1; i++) {
