                        float pr = amt * (mm == 1 ? 1.6 : (mm == 3 ? 0.5 : 0.8));
                        if (hs(id, 12.0 + fl) > pr) continue;
                        float h1 = hs(id, 13.0 + fl), h2 = hs(id, 14.0 + fl), h3 = hs(id, 15.0 + fl);
                        float rate = tsp * (mm == 3 ? 0.18 : (mm == 1 ? 0.9 : 0.4)) * (0.6 + 0.8 * h1);
                        float nn = time * rate + h2 * 10.0;
                        float cyc = floor(nn), ph = fract(nn);
