                            pp = (id + float2(0.5)) * cs + float2(sin(wt * 1.3 + h1 * 6.0), cos(wt * 0.9 + h3 * 6.0)) * cs * 0.32 * amzp_turb;
                            rad = (9.0 + 9.0 * h1) * zs;
                            bright = 0.2 + 0.8 * pulse(fract(time * rate * 0.6 + h2), tws * 0.5 + 0.5);
                        } else if (mm == 2) {
