                            bright = pulse(ph, tws + 2.0);
                        } else {
                            rad = (2.5 + 4.5 * h1 * h1) * zs;
                            bright = pulse(ph, tws);
                            rot += (h3 - 0.5) * 0.8 * amzp_turb;
