            float nsec = floor(10.0 + amt * 110.0);
            float dth = 6.2831853 / nsec;
            float Rm = max(amzp_radius, 10.0) * sc;
            float vsg = int(amzp_mode) == 4 ? 1.0 : -1.0;
            float crd = 70.0 * sc;
            for (int l = 0; l < 5; l++) {
                if (l >= nl) break;
                float fl = float(l);
                float dp = nl > 1 ? fl / float(nl - 1) : 0.5;
                float zs = mix(0.7, 1.5, dp);
                float zv = mix(0.6, 1.4, dp);
                float vel = vsg * amzp_driftSpeed * 140.0 * zv;
                float sw = int(amzp_mode) == 5 ? amzp_swirl : amzp_swirl * 0.25;
                float R0 = 160.0 * sc;
                float rho = r - vel * evo;
                float th0 = th - sw * evo * 0.5 * R0 / (r + R0) * zv;
                float2 base = float2(floor(th0 / dth), floor(rho / crd));
                for (int a = -1; a <= 1; a++) {
                    for (int b = -1; b <= 1; b++) {
                        float2 id = float2(mod(base.x + float(a), nsec), base.y + float(b));
                        if (hs(id, 31.0 + fl) > 0.55) continue;
                        float h1 = hs(id, 32.0 + fl), h2 = hs(id, 33.0 + fl), h3 = hs(id, 34.0 + fl), h4 = hs(id, 35.0 + fl);
                        float rp = (base.y + float(b) + h2) * crd + vel * evo;
                        if (rp < 0.0) continue;
