        if (int(amzp_mode) == 6 || int(amzp_mode) == 7) {
            float nat = int(amzp_mode) == 6 ? -35.0 : -90.0;
            float da = radians(nat + amzp_driftAngle);
            float2 dir = float2(cos(da), -sin(da));
            float2 pr = float2(-dir.y, dir.x);
            bool met = int(amzp_mode) == 6;
            for (int l = 0; l < 5; l++) {
                if (l >= nl) break;
                float fl = float(l);
                float dp = nl > 1 ? fl / float(nl - 1) : 0.5;
                float zs = mix(0.6, 1.5, dp);
                float zv = mix(0.6, 1.4, dp);
                float cu = (met ? 900.0 : 360.0) * sc * mix(1.0, 1.3, dp);
                float cv = (met ? 190.0 : 42.0) * sc * mix(0.9, 1.3, dp);
                float vel = (met ? 900.0 : 600.0) * amzp_driftSpeed * zv;
                float2 uvw = float2(dot(w, dir), dot(w, pr));
                float2 f = float2((uvw.x - vel * evo) / cu, uvw.y / cv) + float2(fl * 9.7, fl * 3.3);
                float2 ci = floor(f);
                for (int j = -1; j <= 1; j++) {
                    for (int i = -1; i <= 1; i++) {
                        float2 id = ci + float2(float(i), float(j));
                        if (hs(id, 41.0 + fl) > amt * (met ? 0.5 : 0.5)) continue;
                        float h1 = hs(id, 42.0 + fl), h2 = hs(id, 43.0 + fl), h3 = hs(id, 44.0 + fl);
                        float2 pp = float2((id.x + h1) * cu, (id.y + h2) * cv);
                        float2 d = float2(f.x * cu, f.y * cv) - pp;
                        float rad = (met ? 3.2 : 1.4) * (0.7 + 0.6 * h3) * zs * max(amzp_size, 0.01) * sc;
                        float Ls = (met ? 300.0 : 70.0) * (0.6 + 0.8 * h3) * amzp_trail * sc;
                        float a = -d.x;
                        float bright = mix(0.6, 1.0, dp) * (0.6 + 0.4 * pulse(fract(time * tsp * 0.2 * (0.6 + h3) + h1 * 5.0), 0.8));
                        float2 g = glim(float2(d.x, d.y), rad, radians(amzp_starRot), cv * 0.95, 1.0);
                        float tr = 0.0;
                        if (a > 0.0 && Ls > 0.0) {
                            float wd = rad * (0.25 + 0.75 * exp(-a / Ls * 2.0));
                            tr = exp(-a / Ls * 3.0) * (exp(-pow(d.y / wd, 2.0)) * 0.9 + exp(-abs(d.y) / (wd * 4.0)) * 0.12 * amzp_glow);
                        }
                        float3 col = pcol(h3);
                        L += (float3(g.x) * 0.8 + col * (g.x * 0.4 + g.y * (met ? 1.0 : 0.5) + tr)) * bright;
                    }
                }
            }
        }
        L *= max(amzp_brightness, 0.0);
        amzOutput = nmBlend(orig, nmGradMap(lightFx(L)));
    }
    void amzRender() {
        nmMain();
        if (!(amzp_overdrawOn>0.5)) amzOutput *= amzTexture(0, amzScreenNorm()).a;
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
